      { type: "prayer", id: "th-pray", title: "My ‘even if’ prayer (written)", minutes: 3, mood: "calm", style: "write",
        tip: "An ‘even if’ prayer has two parts: ‘God, you CAN…’ and ‘But even if…’. Today write your own — then take it home and keep praying it.",
        opening: "On your paper, write at the top: ‘God, you are able.’ We’ll add a line for each part.",
        phases: [
          { name: "Wow", lead: "Write one thing this week showed you that God is able to do.",
            prompts: ["You are able to save from fire and lions.", "You are the living God, and your kingdom will never end."],
            starter: "God, you are able to…", seconds: 35, aloud: "God, you are able — you are the living God!" },
          { name: "Sorry", lead: "Silently: is there a time you only trusted God when things went your way?",
            prompts: ["Sorry for giving up on you when I didn’t get what I wanted.", "Sorry for being afraid to stand up for you."],
            starter: "Sorry for…", seconds: 25, aloud: "God, we’re sorry for trusting you only when it’s easy." },
          { name: "Thanks", lead: "Write a thank you for Jesus, who came out of the sealed tomb alive.",
            prompts: ["Thank you, Jesus, that you rose again on the third morning.", "Thank you that you were with Daniel in the dark — and you are with me."],
            starter: "Thank you, Jesus, for…", seconds: 35, aloud: "Thank you, Jesus — you are alive, and you are with us!" },
          { name: "Please", lead: "Write your own ‘even if’ prayer about something real.",
            prompts: ["Please, God, you can… But even if you don’t, I will trust you.", "Please help me be quietly brave for you this week."],
            starter: "God, you can… But even if…", seconds: 45, aloud: "God, you can do anything. But even if you don’t, we will still trust you." }
        ],
        closing: "Let’s say Daniel 3:17–18 together as our closing prayer. Amen!",
        notes: "Students take their prayers home with the challenge card. Some may write about very personal things — don’t ask them to share." }
